    /// </summary>
    public static MainWindowHostServices CreateHostServices(
        string mcpBaseUrl,
        string? initialApiKey = null,
        string? bearerToken = null,
        IUiDispatcherService? uiDispatcher = null,
        IClipboardService? clipboardService = null,
        ISystemNotificationService? systemNotification = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(mcpBaseUrl);

        var normalizedBaseUrl = NormalizeMcpBaseUrl(mcpBaseUrl);
        var resolvedApiKey = string.IsNullOrWhiteSpace(initialApiKey)
            ? McpServerRestClientFactory.TryResolveApiKey(normalizedBaseUrl)
            : initialApiKey.Trim();
        var defaultMcpBaseUri = new Uri(normalizedBaseUrl, UriKind.Absolute);

        var workspaceContext = new WorkspaceContextViewModel
        {
            ActiveWorkspacePath = string.Empty
        };

        var activeBearer = string.IsNullOrWhiteSpace(bearerToken) ? null : bearerToken.Trim();
        var hostIdentityProvider = new AvaloniaHostIdentityProvider(
            resolvedApiKey,
            activeBearer,
            () => workspaceContext.ActiveWorkspacePath);

        // Create shared pre-authenticated clients
        var client = McpServerRestClientFactory.Create(
            normalizedBaseUrl,
            timeout: TimeSpan.FromSeconds(300),
            apiKey: resolvedApiKey,
            bearerToken: activeBearer);

        workspaceContext.ActiveWorkspacePath = client.WorkspacePath ?? string.Empty;

        var promptClient = McpServerRestClientFactory.Create(
            normalizedBaseUrl,
            timeout: TimeSpan.FromMinutes(15),
            apiKey: resolvedApiKey,
            bearerToken: activeBearer);

        // Create services via factory (share clients)
        var sessionLogService = ServiceFactoryInstance.CreateSessionLogService(client);
        var todoService = ServiceFactoryInstance.CreateTodoService(client, promptClient);
        var workspaceService = ServiceFactoryInstance.CreateWorkspaceService(client, defaultMcpBaseUri);
        var voiceService = ServiceFactoryInstance.CreateVoiceService(
            normalizedBaseUrl,
            apiKey: resolvedApiKey,
            bearerToken: activeBearer,
            resolveBaseUrl: () => normalizedBaseUrl,
            resolveBearerToken: hostIdentityProvider.GetBearerToken,
            resolveApiKey: hostIdentityProvider.GetApiKey,
            resolveWorkspacePath: hostIdentityProvider.GetWorkspacePath);
        var eventStreamService = ServiceFactoryInstance.CreateEventStreamService(
            normalizedBaseUrl,
            apiKey: resolvedApiKey,
            bearerToken: activeBearer,
            resolveBaseUrl: () => normalizedBaseUrl,
            resolveBearerToken: hostIdentityProvider.GetBearerToken,
            resolveApiKey: hostIdentityProvider.GetApiKey,
            resolveWorkspacePath: hostIdentityProvider.GetWorkspacePath);

        var hostContext = new AvaloniaMcpContext(client, workspaceContext, hostIdentityProvider);

        var clipboard = clipboardService ?? new NoOpClipboardService();
        var uiDisp = uiDispatcher ?? new ImmediateUiDispatcherService();
        var sysNotif = systemNotification ?? NoOpSystemNotificationService.Instance;

        // Full host bundle composition (H1 impl req-20260704T002017Z-001-h1-impl-factory-move-fresh).
        // Factory owns DI, clients, runtime. Thin VM entry only delegates here.
        var runtimeServices = BuildRuntimeServices(clipboard, uiDisp, sysNotif, workspaceContext);
        var runtime = new UiCoreHostRuntime(runtimeServices, workspaceContext, ownsServices: true);
        return new MainWindowHostServices(
            normalizedBaseUrl,
            resolvedApiKey,
            activeBearer,
            hostIdentityProvider,
            hostContext,
            client,
            todoService,
            workspaceService,
            voiceService,
            sessionLogService,
            eventStreamService,
            runtime);
    }

    private static ServiceProvider BuildRuntimeServices(
        IClipboardService clipboard,
        IUiDispatcherService uiDispatcher,
        ISystemNotificationService systemNotification,
        WorkspaceContextViewModel workspaceContext)
    {
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddSingleton(uiDispatcher);
        services.AddSingleton(clipboard);
        services.AddSingleton(systemNotification);
        services.AddCqrsDispatcher();
        services.AddCqrsLoggerProvider();
        services.AddUiCore();
        services.AddSingleton(workspaceContext);

        services.AddSingleton<DeferredMainWindowCommandTargetAccessor>();
        services.TryAddSingleton<Commands.ICommandTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.INavigationTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IRequestDetailsTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IPreviewTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IArchiveTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.ISessionDataTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IClipboardTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IConfigTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IUiDispatchTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.ITodoCopilotTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IWorkspaceSwitchTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.ILoadWorkspaceConnectionsTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IWorkspaceHealthTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());
        services.TryAddSingleton<Commands.IAgentEventStatusTarget>(sp => sp.GetRequiredService<DeferredMainWindowCommandTargetAccessor>().RequireTarget());

        return services.BuildServiceProvider();
    }

    private static string NormalizeMcpBaseUrl(string mcpBaseUrl)
    {
        if (string.IsNullOrWhiteSpace(mcpBaseUrl))
            throw new InvalidOperationException("MCP base URL is required.");

        var trimmed = mcpBaseUrl.Trim().TrimEnd('/');
        if (!Uri.TryCreate(trimmed, UriKind.Absolute, out var uri))
            throw new InvalidOperationException("MCP base URL must be an absolute URI.");

        return uri.ToString().TrimEnd('/');
    }
}
